import "core-js/modules/es.array.push.js";
/*eslint-disable*/
import VendorReportsub from "@/components/VendorManagement/VendorReportsub.vue";
import VendorTransaction from "@/components/VendorManagement/VendorTransaction.vue";
import ExpenseReport from "@/components/ExpensesManagement/ExpenseReport.vue";
import VendorApproval from "@/components/VendorManagement/VendorApproval.vue";
import InitiateTransaction from "@/components/VendorManagement/VendorPopups/InitiateTransaction.vue";
import SnackBar from "@/components/SnackBar.vue";
import AssetSuppliersList from "@/components/Asset/AdminApps/AssetSuppliersList.vue";
import BulkIndex from "@/components/TicketManagement/BulkIndex.vue";
import AddVendorCreation from "@/components/Asset/Popups/AddVendorCreation.vue";
import AddVendorPrefix from "@/components/Asset/Popups/AddVendorPrefix.vue";
import { export_vendor_data } from "@/graphql/queries";
import { getS3SignedUrl } from "@/mixins/S3GetStorageFile.js";
import { API, graphqlOperation } from "aws-amplify";
import * as XLSX from "xlsx";
const FileSaver = require("file-saver");
import axios from "axios";
export default {
  components: {
    VendorTransaction,
    VendorApproval,
    ExpenseReport,
    VendorReportsub,
    SnackBar,
    InitiateTransaction,
    AssetSuppliersList,
    BulkIndex,
    AddVendorCreation,
    AddVendorPrefix
  },
  data: () => {
    // Set default dates (last month to today)
    let today = new Date();
    let lastMonth = new Date();
    lastMonth.setMonth(today.getMonth() - 1);
    return {
      toggle_exclusive: "vendor_transaction",
      componentCheck: 0,
      SnackBarComponent: {},
      vendorInitate: false,
      categoryKey: 0,
      cardHeight: 0,
      windowHeight: 0,
      // Filter related properties
      showFilterDrawer: false,
      goLoading: false,
      datePicker: false,
      datePickerTo: false,
      tempDate: lastMonth.toISOString().substr(0, 10),
      tempDateTo: today.toISOString().substr(0, 10),
      computedDateDisplay: "",
      dataDisplayFormatted: "",
      selectStatusType: "ALL",
      // Vendor management properties
      supplierAddition: false,
      addPrefixDialog: false,
      prefixData: "",
      prefix: "",
      excelTableData: [],
      excelHeaders: []
    };
  },
  created() {
    // Initialize display dates
    this.computedDateDisplay = this.formatDate(this.tempDate);
    this.dataDisplayFormatted = this.formatDate(this.tempDateTo);
  },
  mounted() {
    this.cardHeight = window.innerHeight - 125;
    this.windowHeight = window.innerHeight - 200;
  },
  computed: {
    activeFiltersCount() {
      let count = 0;

      // Count date filters
      if (this.computedDateDisplay && this.computedDateDisplay !== "") {
        count++;
      }
      if (this.dataDisplayFormatted && this.dataDisplayFormatted !== "") {
        count++;
      }

      // Count status filter (if not default)
      if (this.selectStatusType && this.selectStatusType !== "ALL") {
        count++;
      }
      return count;
    }
  },
  methods: {
    error_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
    },
    success_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
      this.vendorInitate = false;
    },
    category_refresh() {
      this.categoryKey += 1;
    },
    add_category() {
      this.componentCheck = 2;
      this.vendorInitate = true;
    },
    add_vendor() {
      // Open add vendor dialog
      this.componentCheck = 3;
      this.supplierAddition = true;
    },
    export_data() {
      // Export functionality based on current tab
      if (this.toggle_exclusive == 'vendor_list') {
        this.export_vendor();
      } else {
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "green",
          SnackbarText: "Export functionality will be implemented based on current tab.",
          timeout: 5000,
          Top: true
        };
      }
    },
    bulk_import() {
      // Bulk import functionality - handled by BulkIndex component
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: "Bulk import functionality is available in the Vendors tab.",
        timeout: 5000,
        Top: true
      };
    },
    generate_report() {
      // Generate report functionality
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: "Report generation functionality will be implemented.",
        timeout: 5000,
        Top: true
      };
    },
    open_settings() {
      // Open vendor prefix settings
      this.componentCheck = 5;
      this.addPrefixDialog = true;
      this.prefixData = this.prefix;
    },
    // Add vendor methods from AssetSuppliersList
    add_supp() {
      this.componentCheck = 3;
      this.supplierAddition = true;
    },
    Add_prefix() {
      this.componentCheck = 5;
      this.addPrefixDialog = true;
      this.prefixData = this.prefix;
    },
    download_item() {
      const headers = ["Billing Name", "Address 1 *", "Address 2", "Primary Name", "Primary Country Code", "Primary Contact Number", "Primary Email", "Secondary Name", "Secondary Country Code", "Secondary Contact Number", "Secondary Email", "Beneficiary Name", "Bank and Branch Name", "Beneficiary Account Number", "IFSC Code", "GST Id", "PAN Id", "CIN Id"];
      let firstName = this.$store.getters.GetUserObj?.organization?.organization_team_id || "";
      let fileName = firstName ? ` ${firstName}_Suppliers/Vendors Template.xlsx` : "Suppliers/Vendors Template.xlsx";
      const ws = XLSX.utils.aoa_to_sheet([headers]);
      const wb = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(wb, ws, "Sheet1");
      XLSX.writeFile(wb, fileName);
    },
    async export_vendor() {
      try {
        let result = await API.graphql(graphqlOperation(export_vendor_data, {
          input: {
            organization_id: this.$store.getters.GetUserObj.organization.organization_id
          }
        }));
        let response = JSON.parse(result.data.export_vendor_data);
        if (response.Status == "SUCCESS") {
          const details = this.$store.getters.GetOrgDetails;
          const signedUrl = await getS3SignedUrl(response.url, details.s3_details);
          if (signedUrl) {
            this.download_items(signedUrl);
          }
        } else {
          this.SnackBarComponent = {
            SnackbarVmodel: true,
            SnackbarColor: "red",
            SnackbarText: "Failed to export vendor data.",
            timeout: 5000,
            Top: true
          };
        }
      } catch (error) {
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
      }
    },
    async download_items(url) {
      let firstName = this.$store.getters.GetUserObj?.organization?.organization_team_id;
      let fileNames = firstName ? firstName + "_" + "Vendors" + ".xlsx" : "_" + "Vendors" + ".xlsx";
      try {
        const response = await axios({
          url: url,
          method: "GET",
          responseType: "blob"
        });
        if (!response.data) {
          throw new Error("No data received from the server.");
        }
        const fileName = fileNames;
        const blob = new Blob([response.data], {
          type: response.headers["content-type"] || "application/octet-stream"
        });
        FileSaver.saveAs(blob, fileName);
      } catch (error) {
        console.error("Error downloading the file:", error);
      }
    },
    handleSuccessbusiness({
      results,
      header
    }) {
      // if (!this.prefix || this.prefix === "N/A") {
      //   this.SnackBarComponent = {
      //     SnackbarVmodel: true,
      //     SnackbarColor: "error",
      //     SnackbarText: "Please add prefix",
      //     timeout: 5000,
      //     Top: true,
      //   };
      //   return;
      // }

      this.excelTableData = results;
      this.$router.push("/home/SupplierUpload");
      this.excelHeaders = header;
      const customerData = {
        excelHeaders: this.excelHeaders,
        excelTableData: this.excelTableData
      };
      this.$store.commit("SetcustomerDetails", customerData);
    },
    beforeUpload(file) {
      const isLt1M = file.size / 1024 / 1024 < 5;
      if (isLt1M) {
        return true;
      }
      return false;
    },
    // Filter drawer methods
    closeFilterDrawer() {
      this.showFilterDrawer = false;
    },
    applyFilterFromDrawer() {
      this.goLoading = true;
      // Call the child component's filter method
      if (this.$refs.vendorTransaction) {
        this.$refs.vendorTransaction.getexpense_list();
      }
      this.closeFilterDrawer();
      this.goLoading = false;
    },
    clearFilters() {
      // Reset to default dates (last month to today)
      let today = new Date();
      let lastMonth = new Date();
      lastMonth.setMonth(today.getMonth() - 1);
      this.tempDate = lastMonth.toISOString().substr(0, 10);
      this.tempDateTo = today.toISOString().substr(0, 10);
      this.computedDateDisplay = this.formatDate(this.tempDate);
      this.dataDisplayFormatted = this.formatDate(this.tempDateTo);
      this.selectStatusType = "ALL";

      // Refresh the vendor transaction list with cleared filters
      if (this.$refs.vendorTransaction) {
        this.$refs.vendorTransaction.getexpense_list();
      }
    },
    // Date picker methods
    saveDate() {
      if (this.tempDate) {
        this.computedDateDisplay = this.formatDate(this.tempDate);
      }
      this.datePicker = false;
    },
    saveDateTo() {
      if (this.tempDateTo) {
        this.dataDisplayFormatted = this.formatDate(this.tempDateTo);
      }
      this.datePickerTo = false;
    },
    // Method to open date picker and set temp date
    openDatePicker() {
      if (!this.tempDate) {
        let lastMonth = new Date();
        lastMonth.setMonth(lastMonth.getMonth() - 1);
        this.tempDate = lastMonth.toISOString().substr(0, 10);
      }
      this.datePicker = true;
    },
    openDatePickerTo() {
      if (!this.tempDateTo) {
        this.tempDateTo = new Date().toISOString().substr(0, 10);
      }
      this.datePickerTo = true;
    },
    formatDate(dateString) {
      if (!dateString) return "";
      const date = new Date(dateString);
      return date.toLocaleDateString("en-GB"); // DD/MM/YYYY format
    },
    handleFilterApplied(filterData) {
      // This method will be called when the child component applies the filter
      console.log("Filter applied:", filterData);
    }
  }
};
